import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第七卦 師 地水師 坤上坎下","description":"周易 - 第七卦 師 地水師 坤上坎下","frontmatter":{"title":"第七卦 師 地水師 坤上坎下","description":"周易 - 第七卦 師 地水師 坤上坎下"},"headers":[],"relativePath":"classics/zhouyi/008.md","filePath":"classics/zhouyi/008.md"}'),l={name:"classics/zhouyi/008.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="師" tabindex="-1">師 <a class="header-anchor" href="#師" aria-label="Permalink to “師”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>貞，丈人，吉無咎。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>師，眾也，貞正也，能以眾正，可以王矣。剛中而應，行險而順，以此毒天下，而民從之，吉又何咎矣。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>地中有水，師；君子以容民畜眾。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>師出以律，否臧兇。象曰：師出以律， 失律兇也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>在師中，吉無咎，王三錫命。象曰：在師中吉，承天寵也。王三錫命，懷萬邦也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>師或輿尸，兇。象曰：師或輿尸，大無功也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>師左次，無咎。象曰：左次無咎，未失常也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>田有禽，利執言，無咎。長子帥師，弟子輿尸，貞兇。象曰：長子帥師，以中行也。弟子輿師，使不當也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>大君有命，開國承家，小人勿用。象曰：大君有命，以正功也。小人勿用，必亂邦也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
